package com.razedragon.tinylab

import android.content.Context
import android.media.AudioAttributes
import android.media.MediaPlayer
import android.media.SoundPool
import java.io.File
import java.io.FileOutputStream
import java.nio.ByteBuffer
import java.nio.ByteOrder
import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.exp
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min
import kotlin.math.pow
import kotlin.math.sin
import kotlin.random.Random

/**
 * All sound is generated by code the first time the game runs (no audio files needed),
 * saved to the phone's cache as small WAV files, then played with SoundPool / MediaPlayer.
 */
class Sound(private val context: Context) {

    enum class Fx { CLICK, POP, BUBBLE, COIN, DISCOVER, EAT, GROW, PET, DENIED, BREW_DONE, STIR,
        CHIRP, GIGGLE, WHEE, CHOMP, PURR, SNEEZE, YAWN, BOING, RIBBIT, CLINK, LEVELUP }

    var sfxOn = true
        set(v) { field = v; if (!v) setAmbient(false, false, false, false) }
    var musicOn = true
        set(v) { field = v; updateMusic() }

    private val rate = 22050
    private val pool: SoundPool = SoundPool.Builder()
        .setMaxStreams(16)
        .setAudioAttributes(AudioAttributes.Builder()
            .setUsage(AudioAttributes.USAGE_GAME)
            .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
            .build())
        .build()
    private val ids = IntArray(Fx.values().size)
    @Volatile private var ready = false
    @Volatile private var dayPlayer: MediaPlayer? = null
    @Volatile private var nightPlayer: MediaPlayer? = null
    @Volatile private var spookyPlayer: MediaPlayer? = null
    /** During Shroomoween a spooky little tune takes over from the usual music. */
    var spooky = false
    @Volatile private var appActive = true
    @Volatile private var released = false

    // Background ambience loops: birds, crickets, rain, campfire
    private val ambIds = IntArray(4)
    private val ambStreams = IntArray(4)
    private val ambOn = BooleanArray(4)
    private val ambVol = floatArrayOf(0.22f, 0.2f, 0.32f, 0.3f)
    @Volatile private var ambReady = false

    // 0 = day music, 1 = night music; crossfades smoothly
    private var nightTarget = 0f
    private var nightMix = 0f
    private val musicVol = 0.42f

    private fun newPlayer(path: String): MediaPlayer {
        val mp = MediaPlayer()
        mp.setAudioAttributes(AudioAttributes.Builder()
            .setUsage(AudioAttributes.USAGE_GAME)
            .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
            .build())
        mp.setDataSource(path)
        mp.isLooping = true
        mp.setVolume(0f, 0f)
        mp.prepare()
        return mp
    }

    init {
        Thread {
            try {
                val dir = File(context.cacheDir, "tinylab_sound_v5").apply { mkdirs() }
                for (fx in Fx.values()) {
                    val f = File(dir, fx.name.lowercase() + ".wav")
                    if (!f.exists()) writeWav(f, synth(fx))
                    ids[fx.ordinal] = pool.load(f.path, 1)
                }
                ready = true
                val m = File(dir, "music.wav")
                if (!m.exists()) writeWav(m, music(false))
                val day = newPlayer(m.path)
                if (released) { day.release(); return@Thread }
                dayPlayer = day
                applyVolumes()
                updateMusic()
                val amb = arrayOf("amb_birds" to { birds() }, "amb_crickets" to { crickets() }, "amb_rain" to { rain() }, "amb_fire" to { fire() })
                for ((k, pair) in amb.withIndex()) {
                    val f = File(dir, pair.first + ".wav")
                    if (!f.exists()) writeWav(f, pair.second())
                    ambIds[k] = pool.load(f.path, 1)
                }
                Thread.sleep(300)
                ambReady = true
                val n = File(dir, "music_night.wav")
                if (!n.exists()) writeWav(n, music(true))
                val night = newPlayer(n.path)
                if (released) { night.release(); return@Thread }
                nightPlayer = night
                applyVolumes()
                updateMusic()
                val sp = File(dir, "music_spooky.wav")
                if (!sp.exists()) writeWav(sp, spookyMusic())
                val spk = newPlayer(sp.path)
                if (released) { spk.release(); return@Thread }
                spookyPlayer = spk
                applyVolumes()
                updateMusic()
            } catch (_: Exception) {
                // Sound is a nice-to-have: the game keeps working silently if anything fails.
            }
        }.start()
    }

    fun play(fx: Fx, volume: Float = 1f, pitch: Float = 1f) {
        if (!sfxOn || !ready) return
        pool.play(ids[fx.ordinal], volume, volume, 1, 0, pitch.coerceIn(0.5f, 2f))
    }

    fun ambientReady() = ambReady

    /** Turns the looping background sounds on or off. */
    fun setAmbient(birds: Boolean, crickets: Boolean, rain: Boolean, fire: Boolean) {
        if (!ambReady) return
        val want = booleanArrayOf(birds, crickets, rain, fire)
        for (k in 0..3) {
            val on = want[k] && sfxOn && appActive
            if (on == ambOn[k]) continue
            ambOn[k] = on
            if (on) ambStreams[k] = pool.play(ambIds[k], ambVol[k], ambVol[k], 0, -1, 1f)
            else if (ambStreams[k] != 0) { pool.stop(ambStreams[k]); ambStreams[k] = 0 }
        }
    }

    /** Call every frame: fades between day and night music. */
    fun update(dt: Float, night: Boolean) {
        nightTarget = if (night && nightPlayer != null) 1f else 0f
        if (nightMix != nightTarget) {
            nightMix = if (nightMix < nightTarget) min(nightTarget, nightMix + dt * 0.3f) else max(nightTarget, nightMix - dt * 0.3f)
            applyVolumes()
        }
        val st = if (spooky && spookyPlayer != null) 1f else 0f
        if (spookyMix != st) {
            spookyMix = if (spookyMix < st) min(st, spookyMix + dt * 0.4f) else max(st, spookyMix - dt * 0.4f)
            applyVolumes()
        }
    }
    private var spookyMix = 0f

    private fun applyVolumes() {
        try {
            val normal = 1f - spookyMix
            dayPlayer?.setVolume(musicVol * (1f - nightMix) * normal, musicVol * (1f - nightMix) * normal)
            nightPlayer?.setVolume(musicVol * nightMix * normal, musicVol * nightMix * normal)
            spookyPlayer?.setVolume(musicVol * spookyMix, musicVol * spookyMix)
        } catch (_: IllegalStateException) {}
    }

    fun onAppPause() {
        appActive = false; updateMusic()
        for (k in 0..3) if (ambOn[k]) { pool.stop(ambStreams[k]); ambStreams[k] = 0; ambOn[k] = false }
    }
    fun onAppResume() { appActive = true; updateMusic() }

    fun release() {
        released = true
        synchronized(this) {
            dayPlayer?.release(); dayPlayer = null
            nightPlayer?.release(); nightPlayer = null
            spookyPlayer?.release(); spookyPlayer = null
        }
        pool.release()
    }

    @Synchronized
    private fun updateMusic() {
        for (p in listOfNotNull(dayPlayer, nightPlayer, spookyPlayer)) {
            try {
                if (musicOn && appActive) { if (!p.isPlaying) p.start() }
                else if (p.isPlaying) p.pause()
            } catch (_: IllegalStateException) {}
        }
    }

    // ---------- Ambience ----------

    private fun birds(): FloatArray {
        val out = FloatArray(rate * 6)
        val r = Random(9)
        var at = 0.2f
        while (at < 5.6f) {
            val base = 2200f + r.nextFloat() * 1600f
            val notes = 2 + r.nextInt(4)
            for (k in 0 until notes) {
                val st = ((at + k * 0.09f) * rate).toInt()
                val len = (0.07f * rate).toInt()
                var ph = 0.0
                for (i in 0 until len) {
                    if (st + i >= out.size) break
                    val p = i / len.toFloat()
                    ph += (base * (1f + 0.35f * sin(p * PI).toFloat()) * (if (k % 2 == 0) 1f else 1.15f)) / rate
                    out[st + i] += sin(2 * PI * ph).toFloat() * sin(p * PI).toFloat() * 0.18f
                }
            }
            at += 0.6f + r.nextFloat() * 1.3f
        }
        return out
    }

    private fun crickets(): FloatArray {
        val out = FloatArray(rate * 4)
        for ((v, f) in floatArrayOf(4300f, 4700f).withIndex()) {
            for (i in out.indices) {
                val tt = i / rate.toFloat()
                val chirpOn = ((tt * 1.6f + v * 0.37f) % 1f) < 0.32f
                if (!chirpOn) continue
                val pulse = 0.5f + 0.5f * sin(2 * PI * 32 * tt).toFloat()
                out[i] += sin(2 * PI * f * tt).toFloat() * pulse * 0.06f
            }
        }
        return out
    }

    private fun rain(): FloatArray {
        val n = rate * 5
        val out = FloatArray(n)
        val r = Random(4)
        var y = 0f
        for (i in 0 until n) { y += 0.18f * ((r.nextFloat() * 2f - 1f) - y); out[i] = y * 0.9f }
        // a few drips
        repeat(40) {
            val st = r.nextInt(n - 2000)
            val f = 1200f + r.nextFloat() * 1500f
            for (i in 0 until 600) out[st + i] += sin(2 * PI * f * i / rate).toFloat() * exp(-i / 120f) * 0.15f
        }
        return out
    }

    private fun fire(): FloatArray {
        val n = rate * 4
        val out = FloatArray(n)
        val r = Random(6)
        var y = 0f
        for (i in 0 until n) { y += 0.05f * ((r.nextFloat() * 2f - 1f) - y); out[i] = y * 0.8f }
        repeat(70) {   // crackles
            val st = r.nextInt(n - 400)
            val amp = 0.2f + r.nextFloat() * 0.4f
            for (i in 0 until 200) out[st + i] += (r.nextFloat() * 2f - 1f) * amp * exp(-i / 30f)
        }
        return out
    }

    // ---------- Synthesis ----------

    private enum class Wave { SINE, SQUARE, SAW, TRI }

    private fun osc(phase: Double, w: Wave): Float {
        val f = (phase - floor(phase)).toFloat()
        return when (w) {
            Wave.SINE -> sin(2 * PI * phase).toFloat()
            Wave.SQUARE -> if (f < 0.5f) 1f else -1f
            Wave.SAW -> 2f * f - 1f
            Wave.TRI -> 4f * abs(f - 0.5f) - 1f
        }
    }

    /** A tone that glides from f0 to f1 and fades out. */
    private fun sweep(dur: Float, f0: Float, f1: Float, w: Wave, vol: Float): FloatArray {
        val n = (dur * rate).toInt()
        val out = FloatArray(n)
        var phase = 0.0
        for (i in 0 until n) {
            val t = i / n.toFloat()
            val f = f0 * (f1 / f0).toDouble().pow(t.toDouble())
            phase += f / rate
            val env = min(1f, i / (0.003f * rate)) * (1f - t) * (1f - t)
            out[i] = osc(phase, w) * env * vol
        }
        return out
    }

    /** Filtered white noise, for explosions. Lower `smooth` = deeper rumble. */
    private fun noise(dur: Float, vol: Float, smooth: Float): FloatArray {
        val n = (dur * rate).toInt()
        val out = FloatArray(n)
        var y = 0f
        val rnd = Random(7)
        for (i in 0 until n) {
            val t = i / n.toFloat()
            y += smooth * ((rnd.nextFloat() * 2f - 1f) - y)
            out[i] = y * vol * exp(-4f * t) * 2.5f
        }
        return out
    }

    /** A quick run of notes, like a coin or power-up jingle. */
    private fun notes(freqs: FloatArray, each: Float, w: Wave, vol: Float): FloatArray {
        val per = (each * rate).toInt()
        val out = FloatArray(per * freqs.size + per)
        for ((k, f) in freqs.withIndex()) {
            val len = if (k == freqs.size - 1) per * 2 else per
            for (i in 0 until len) {
                val t = i / len.toFloat()
                val env = min(1f, i / (0.002f * rate)) * (1f - t)
                out[k * per + i] += osc(f.toDouble() * i / rate, w) * env * vol
            }
        }
        return out
    }

    private fun mix(a: FloatArray, b: FloatArray): FloatArray {
        val out = FloatArray(maxOf(a.size, b.size))
        for (i in a.indices) out[i] += a[i]
        for (i in b.indices) out[i] += b[i]
        return out
    }

    /** Feedback echo, for a soft roomy sound. */
    private fun echo(buf: FloatArray, delaySec: Float, feedback: Float, mix: Float): FloatArray {
        val d = (delaySec * rate).toInt()
        val wet = FloatArray(buf.size + d * 4)
        for (i in buf.indices) wet[i] += buf[i]
        for (i in d until wet.size) wet[i] += wet[i - d] * feedback
        val out = FloatArray(wet.size)
        for (i in out.indices) out[i] = (if (i < buf.size) buf[i] else 0f) * (1f - mix * 0.5f) + (wet[i] - (if (i < buf.size) buf[i] else 0f)) * mix
        return out
    }

    /** A cute little voice: quick pitch-bent sine syllables. */
    private fun chirp(freqs: FloatArray, each: Float): FloatArray {
        val per = (each * rate).toInt()
        val out = FloatArray(per * freqs.size + per)
        var ph = 0.0
        for ((k, f) in freqs.withIndex()) {
            for (i in 0 until per) {
                val p = i / per.toFloat()
                val freq = f * (1f + 0.25f * sin(p * PI).toFloat())
                ph += freq / rate
                val env = sin(p * PI).toFloat()
                out[k * per + i] += sin(2 * PI * ph).toFloat() * env * 0.35f
            }
        }
        return out
    }

    /** A kalimba / music-box pluck: a sine with a quickly fading bell overtone. */
    private fun pluck(out: FloatArray, start: Int, freq: Float, vol: Float, len: Float = 0.9f) {
        val n = (len * rate).toInt()
        for (i in 0 until n) {
            val idx = start + i
            if (idx >= out.size) break
            val tt = i / rate.toFloat()
            val env = min(1f, i / (0.002f * rate)) * exp(-5f * tt)
            val bell = exp(-18f * tt)
            out[idx] += (sin(2 * PI * freq * tt).toFloat() + 0.35f * bell * sin(2 * PI * freq * 2.76 * tt).toFloat()) * env * vol
        }
    }

    private fun plucks(freqs: FloatArray, gap: Float, vol: Float, tail: Float = 0.8f): FloatArray {
        val out = FloatArray(((freqs.size * gap + tail) * rate).toInt())
        for ((k, f) in freqs.withIndex()) pluck(out, (k * gap * rate).toInt(), f, vol, tail)
        return out
    }

    private fun synth(fx: Fx): FloatArray = when (fx) {
        Fx.CLICK -> mix(sweep(0.035f, 950f, 620f, Wave.SINE, 0.32f), noise(0.02f, 0.08f, 0.6f))
        Fx.POP -> echo(sweep(0.075f, 320f, 1150f, Wave.SINE, 0.5f), 0.07f, 0.25f, 0.3f)
        Fx.BUBBLE -> {
            val out = FloatArray((0.32f * rate).toInt())
            for ((k, f) in floatArrayOf(380f, 520f, 450f).withIndex()) {
                val b = sweep(0.07f, f, f * 2.2f, Wave.SINE, 0.32f)
                val st = (k * 0.09f * rate).toInt()
                for (i in b.indices) if (st + i < out.size) out[st + i] += b[i]
            }
            out
        }
        Fx.COIN -> echo(plucks(floatArrayOf(1318.5f, 1760f), 0.06f, 0.35f, 0.5f), 0.11f, 0.3f, 0.35f)
        Fx.DISCOVER -> echo(mix(plucks(floatArrayOf(523.3f, 659.3f, 784f, 1046.5f, 1318.5f), 0.085f, 0.4f, 1.2f),
            sweep(0.6f, 2000f, 4000f, Wave.SINE, 0.05f)), 0.16f, 0.35f, 0.4f)
        Fx.EAT -> mix(mix(noise(0.07f, 0.3f, 0.35f), sweep(0.12f, 420f, 260f, Wave.SINE, 0.3f)),
            FloatArray((0.1f * rate).toInt()) + noise(0.07f, 0.25f, 0.35f))
        Fx.GROW -> echo(plucks(floatArrayOf(392f, 523.3f, 659.3f, 784f, 1046.5f), 0.07f, 0.38f, 1f), 0.14f, 0.3f, 0.35f)
        Fx.PET -> echo(plucks(floatArrayOf(880f, 1174.7f), 0.09f, 0.32f, 0.7f), 0.12f, 0.25f, 0.3f)
        Fx.DENIED -> notes(floatArrayOf(330f, 247f), 0.09f, Wave.TRI, 0.28f)
        Fx.BREW_DONE -> echo(mix(noise(0.35f, 0.25f, 0.25f), plucks(floatArrayOf(659.3f, 987.8f, 1318.5f), 0.07f, 0.35f, 0.8f)), 0.13f, 0.3f, 0.35f)
        Fx.STIR -> noise(0.16f, 0.22f, 0.12f)
        Fx.CHIRP -> chirp(floatArrayOf(900f, 1300f), 0.07f)
        Fx.GIGGLE -> chirp(floatArrayOf(1100f, 1400f, 1050f, 1450f, 1150f), 0.055f)
        Fx.WHEE -> echo(mix(sweep(0.55f, 500f, 1500f, Wave.SINE, 0.32f), sweep(0.55f, 750f, 2200f, Wave.TRI, 0.08f)), 0.1f, 0.25f, 0.25f)
        Fx.CHOMP -> mix(mix(noise(0.05f, 0.4f, 0.4f), sweep(0.07f, 300f, 160f, Wave.SINE, 0.4f)),
            FloatArray((0.12f * rate).toInt()) + mix(noise(0.05f, 0.35f, 0.4f), sweep(0.07f, 280f, 150f, Wave.SINE, 0.35f)))
        Fx.PURR -> {
            val n = (0.6f * rate).toInt()
            FloatArray(n) { i ->
                val tt = i / rate.toFloat()
                (sin(2 * PI * 110 * tt).toFloat() * (0.5f + 0.5f * sin(2 * PI * 22 * tt).toFloat())) * 0.35f * min(1f, tt * 8f) * min(1f, (0.6f - tt) * 6f)
            }
        }
        Fx.SNEEZE -> mix(sweep(0.18f, 600f, 1100f, Wave.SINE, 0.2f), FloatArray((0.2f * rate).toInt()) + noise(0.22f, 0.5f, 0.6f))
        Fx.YAWN -> sweep(0.7f, 520f, 260f, Wave.SINE, 0.25f)
        Fx.BOING -> {
            val n = (0.35f * rate).toInt()
            FloatArray(n) { i ->
                val tt = i / rate.toFloat()
                sin(2 * PI * (180 + 120 * sin(2 * PI * 14 * tt)) * tt).toFloat() * exp(-7f * tt) * 0.4f
            }
        }
        Fx.RIBBIT -> mix(sweep(0.09f, 260f, 200f, Wave.SQUARE, 0.12f), FloatArray((0.13f * rate).toInt()) + sweep(0.1f, 300f, 220f, Wave.SQUARE, 0.12f))
        Fx.CLINK -> echo(plucks(floatArrayOf(2093f), 0.05f, 0.3f, 0.4f), 0.08f, 0.3f, 0.3f)
        // a little "ta-da!" for growing up: a quick run, then a bright chord with a shimmer
        Fx.LEVELUP -> {
            val run = plucks(floatArrayOf(523.3f, 659.3f, 784f), 0.08f, 0.32f, 0.5f)
            val chord = FloatArray((1.3f * rate).toInt())
            for (f in floatArrayOf(1046.5f, 1318.5f, 1568f, 2093f)) pluck(chord, 0, f, 0.18f, 1.2f)
            val out = FloatArray(run.size + chord.size)
            for (i in run.indices) out[i] += run[i]
            val st = (0.26f * rate).toInt()
            for (i in chord.indices) if (st + i < out.size) out[st + i] += chord[i]
            echo(mix(out, FloatArray(st) + sweep(0.9f, 2500f, 5000f, Wave.SINE, 0.04f)), 0.15f, 0.35f, 0.4f)
        }
    }

    /** Shroomoween: a creepy-cute waltz in A minor with a music box, a plodding bass and a little "ooo" choir. */
    private fun spookyMusic(): FloatArray {
        val bpm = 96
        val beat = rate * 60 / bpm
        val bars = 16
        val out = FloatArray(beat * 3 * bars)
        // Am  F  Dm  E  (two bars each), twice
        val roots = floatArrayOf(110f, 87.31f, 73.42f, 82.41f)
        val chords = arrayOf(
            floatArrayOf(220f, 261.63f, 329.63f), floatArrayOf(174.61f, 220f, 261.63f),
            floatArrayOf(146.83f, 174.61f, 220f), floatArrayOf(164.81f, 207.65f, 246.94f))
        val tune = floatArrayOf(880f, 1046.5f, 987.77f, 880f, 830.61f, 880f, 659.25f, 698.46f, 659.25f, 587.33f, 659.25f, 830.61f)
        val rnd = Random(31)
        for (bar in 0 until bars) {
            val ci = (bar / 2) % 4
            val barStart = bar * beat * 3
            // oom-pah-pah: bass on 1, chord plucks on 2 and 3
            for (i in 0 until beat) {
                val idx = barStart + i; if (idx >= out.size) break
                val tt = i / rate.toFloat()
                out[idx] += osc(roots[ci].toDouble() * i / rate, Wave.TRI) * exp(-3f * tt) * 0.22f
            }
            for (b in 1..2) for (f in chords[ci]) pluck(out, barStart + b * beat, f * 2f, 0.035f, 0.35f)
            // ghostly "ooo": a soft wobbling sine on the chord's top note
            if (bar % 2 == 0) {
                val len = beat * 6; val f = chords[ci][2]
                for (i in 0 until len) {
                    val idx = barStart + i; if (idx >= out.size) break
                    val p = i / len.toFloat()
                    val env = min(1f, p * 3f) * min(1f, (1f - p) * 3f)
                    val vib = 1f + 0.012f * sin(2 * PI * 5.5 * i / rate).toFloat()
                    out[idx] += sin(2 * PI * f * vib * i / rate).toFloat() * env * 0.03f
                }
            }
            // music-box melody in bars 1-6 and 9-14
            if (bar % 8 in 1..6) for (b in 0 until 3) {
                if (rnd.nextFloat() < 0.8f) pluck(out, barStart + b * beat, tune[(bar * 3 + b) % tune.size], 0.1f, 1.2f)
            }
        }
        val d = beat / 2
        val wet = out.copyOf()
        for (pass in 0 until 2) for (i in wet.indices) wet[i] += wet[(i - d + wet.size) % wet.size] * 0.3f
        for (i in out.indices) out[i] = ((out[i] * 0.75f + (wet[i] - out[i]) * 0.35f) * 1.4f).coerceIn(-1f, 1f)
        return out
    }

    /** A calm 16-bar loop: soft pads, bass, a music-box melody and arpeggios, with a little echo. */
    private fun music(night: Boolean): FloatArray {
        val bpm = if (night) 64 else 80
        val beat = rate * 60 / bpm
        val bars = 16
        val out = FloatArray(beat * 4 * bars)

        // C  Am  F  G  C  Em  F  G   (two bars each)
        val roots = floatArrayOf(130.81f, 110f, 87.31f, 98f, 130.81f, 82.41f, 87.31f, 98f)
        val chords = arrayOf(
            floatArrayOf(261.63f, 329.63f, 392f), floatArrayOf(220f, 261.63f, 329.63f),
            floatArrayOf(174.61f, 220f, 261.63f), floatArrayOf(196f, 246.94f, 293.66f),
            floatArrayOf(261.63f, 329.63f, 392f), floatArrayOf(164.81f, 196f, 246.94f),
            floatArrayOf(174.61f, 220f, 261.63f), floatArrayOf(196f, 246.94f, 293.66f),
        )
        // pentatonic melody notes (C major pentatonic, upper octave)
        val penta = floatArrayOf(523.25f, 587.33f, 659.25f, 783.99f, 880f, 1046.5f)
        val rnd = Random(21)

        val order = if (night) intArrayOf(1, 2, 0, 3, 1, 5, 2, 7) else intArrayOf(0, 1, 2, 3, 4, 5, 6, 7)
        for (bar in 0 until bars) {
            val ci = order[bar / 2]
            val barStart = bar * beat * 4

            // pad: three soft detuned sines that swell across two bars
            if (bar % 2 == 0) {
                val len = beat * 8
                for (f in chords[ci]) {
                    for (det in floatArrayOf(0.997f, 1.003f)) {
                        for (i in 0 until len) {
                            val idx = barStart + i
                            if (idx >= out.size) break
                            val p = i / len.toFloat()
                            val env = min(1f, p * 5f) * min(1f, (1f - p) * 4f)
                            out[idx] += sin(2 * PI * f * det * i / rate).toFloat() * env * 0.025f
                        }
                    }
                }
            }
            // bass: half notes
            for (h in 0..1) {
                val st = barStart + h * beat * 2
                val n = beat * 2
                for (i in 0 until n) {
                    val idx = st + i
                    if (idx >= out.size) break
                    val tt = i / rate.toFloat()
                    out[idx] += osc(roots[ci].toDouble() * i / rate, Wave.TRI) * exp(-1.6f * tt) * min(1f, i / (0.01f * rate)) * 0.2f
                }
            }
            // arpeggio on eighth notes, quiet
            for (e in 0 until 8) {
                val f = chords[ci][intArrayOf(0, 1, 2, 1, 0, 2, 1, 2)[e]] * 2f
                pluck(out, barStart + e * beat / 2, if (night) f / 2f else f, if (night) 0.035f else 0.045f, 0.6f)
            }
            // melody: phrases in bars 2-7 and 10-15, resting elsewhere
            if (bar % 8 in (if (night) 2..5 else 1..6)) {
                var pos = 0
                while (pos < 8) {
                    val len = if (rnd.nextFloat() < 0.35f) 1 else 2     // eighths
                    if (rnd.nextFloat() < 0.8f) {
                        val strong = pos % 4 == 0
                        val f = if (strong) chords[ci][rnd.nextInt(3)] * 2f else penta[rnd.nextInt(penta.size)]
                        pluck(out, barStart + pos * beat / 2, f, 0.11f, 1.1f)
                    }
                    pos += len
                }
            }
            // soft shaker on the off-beats (not at night)
            for (q in 0 until (if (night) 0 else 4)) {
                val st = barStart + q * beat + beat / 2
                var prev = 0f
                for (i in 0 until (0.035f * rate).toInt()) {
                    val n = rnd.nextFloat() * 2f - 1f
                    val hp = n - prev; prev = n
                    if (st + i < out.size) out[st + i] += hp * 0.018f * (1f - i / (0.035f * rate))
                }
            }
        }
        // echo that wraps around so the loop stays seamless
        val d = beat * 3 / 4
        val wet = out.copyOf()
        for (pass in 0 until 2) for (i in wet.indices) wet[i] += wet[(i - d + wet.size) % wet.size] * 0.28f
        for (i in out.indices) out[i] = ((out[i] * 0.75f + (wet[i] - out[i]) * 0.3f) * 1.4f).coerceIn(-1f, 1f)
        return out
    }

    private fun writeWav(file: File, data: FloatArray) {
        val bytes = ByteBuffer.allocate(44 + data.size * 2).order(ByteOrder.LITTLE_ENDIAN)
        bytes.put("RIFF".toByteArray()); bytes.putInt(36 + data.size * 2)
        bytes.put("WAVE".toByteArray()); bytes.put("fmt ".toByteArray())
        bytes.putInt(16); bytes.putShort(1); bytes.putShort(1)
        bytes.putInt(rate); bytes.putInt(rate * 2); bytes.putShort(2); bytes.putShort(16)
        bytes.put("data".toByteArray()); bytes.putInt(data.size * 2)
        for (v in data) bytes.putShort((v.coerceIn(-1f, 1f) * 32000f).toInt().toShort())
        val tmp = File(file.path + ".tmp")
        FileOutputStream(tmp).use { it.write(bytes.array()) }
        tmp.renameTo(file)
    }
}
